    title: 'Can I meet with you virtually?',
    content:
      'Absolutely. Our entire suite of services is optimized for remote collaboration. Secure video conferencing, shared document suites, and real-time communication tools ensure seamless legal assistance.',
    isOpen: false,
  },
];

export default function Faq() {
  const [currentFaq, setCurrentFaq] = useState(initialFaq);

  const toggleAccordion = (id) => {
    const newFaq = currentFaq.map((item) => {
      if (item.id === id) {
        return { ...item, isOpen: !item.isOpen };
      }
      return item;
    });
    setCurrentFaq(newFaq);
  };

  return (
    <div className="min-h-screen bg-slate-50 p-8 sm:p-12 text-slate-900">
      <div className="max-w-7xl mx-auto">
