            <div className="relative inline-flex h-10 w-20 items-center justify-center rounded-full bg-white shadow-lg shadow-indigo-500/20 p-2 text-indigo-600 ring-2 ring-indigo-500/30 transition-all duration-300 hover:scale-[1.02]">
              <span className="absolute -left-1 -top-1 rounded-full bg-indigo-500/10 p-1 text-xs font-semibold text-indigo-400" aria-hidden="true">
                4
              </span>
              <span className="absolute -right-1 -bottom-1 rounded-full bg-indigo-500/10 p-1 text-xs font-semibold text-indigo-400" aria-hidden="true">
                4
              </span>
              <span className="pointer-events-none absolute inset-0 flex items-center justify-center">
                <Sparkles className="h-5 w-5 text-indigo-400" />
