            </div>
            <h2 className="text-2xl sm:text-3xl font-bold tracking-tight text-slate-900">Frequently Asked Questions</h2>
          </div>
          <p className="mt-4 max-w-md mx-auto text-slate-600">Get the essential answers about our services and legal processes.</p>
        </div>

        {/* Accordion Stack */}
        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3 p-4 sm:p-6 rounded-2xl bg-white/5 border border-white/10 shadow-2xl backdrop-blur-xl transition-all duration-300 hover:shadow-indigo-500/10">
          {currentFaq.map((item) => (
            <div
              key={item.id}
              className="group relative overflow-hidden rounded-2xl bg-white/5 p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-indigo-500/20"
            >
              <div className="absolute inset-0 bg-white/5 backdrop-blur-md transition-opacity duration-300 group-hover:bg-white/10" />
              <div className="relative z-10">
                <div className="flex items-start justify-between">
