                  <button
                    className="flex items-center gap-1.5 text-slate-400 hover:text-indigo-400 transition-colors"
                    onClick={() => toggleAccordion(item.id)}
                  >
                    <ChevronRight className="h-4 w-4 animate-transition-transform" />
                  </button>
                </div>
                <p className="mt-4 text-slate-400">{item.content}</p>
              </div>
              {item.isOpen && (
                <div className="absolute -bottom-1 -right-1 -left-1 -top-1 rounded-2xl bg-white/5 backdrop-blur-xl border border-white/10" />
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

