                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Filter modal toggle */}
      <div className="fixed inset-0 flex items-center justify-center p-4 bg-black/50 backdrop-blur-md animate-fade-in-up duration-700">
        <button
          onClick={() => setActiveTab('all')}
          className="inline-flex items-center gap-2 rounded-xl bg-white/5 p-4 font-medium text-slate-600 shadow-lg transition-all duration-300 hover:bg-white/10"
        >
          <Sparkles className="w-5 h-5" />
          <span>All Categories</span>
        </button>
      </div>
    </div>
  );
}
